#: One megabyte. The largest file this repository legitimately tracks is a tenth
#: of it; the smallest upstream artifact it names is seven times it.
MAX_TRACKED_FILE_BYTES = 1 << 20

GUARD_RULES: tuple[str, ...] = (
    "model_weight_extension",
    "known_checkpoint_filename",
    "runtime_bundle_or_binary",
    "source_or_artifact_archive",
    "dataset_or_biometric_image",
    "forbidden_third_party_path",
    "known_upstream_artifact_digest",
    "oversized_tracked_file",
)


@dataclass(frozen=True, slots=True)
class RepositoryFinding:
    """One tracked path, and the rule it tripped."""

    path: str
    rule: str
    detail: str

    def __post_init__(self) -> None:
        if self.rule not in GUARD_RULES:
            raise RepositoryArtifactError(
                f"{self.rule!r} is not one of the guard's rules; a finding nobody "
                "can trace to a rule is a finding nobody can argue with"
            )


@dataclass(frozen=True, slots=True)
class RepositoryArtifactAudit:
    """What the guard found across every file Git tracks.

    Publishes counts and rule names, never the contents of anything it looked at.
    ``clean`` is the whole summary and it is a conjunction: there is no
    warn-and-continue, because a public repository either holds an upstream byte
    or it does not.
    """

    tracked_file_count: int
    hashed_file_count: int
    rules: tuple[str, ...]
    allowed_exceptions: tuple[str, ...]
    findings: tuple[RepositoryFinding, ...]
    audit_fingerprint: str = ""

    @property
    def every_tracked_file_was_hashed(self) -> bool:
        """Whether the digest rule reached every file the name rules reached.

        The two can differ: a tracked path that this checkout does not have on
        disk — a sparse checkout, or a path Git knows about that the filesystem
        does not — is scanned by name and cannot be hashed.
        """
        return self.hashed_file_count == self.tracked_file_count

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "findings",
            tuple(sorted(self.findings, key=lambda item: (item.path, item.rule))),
        )
        object.__setattr__(self, "rules", tuple(self.rules))
        object.__setattr__(
            self, "allowed_exceptions", tuple(sorted(self.allowed_exceptions))
        )
        # The identity covers what the audit *concluded*, not how many files it
        # happened to look at. The population is a fact about a moment — it grows
        # with every commit, including the commit that publishes this audit — so a
        # fingerprint covering it could never be re-derived from a later tree.
        # The conclusion is stable, and the conclusion is the evidence.
        expected = stable_hash(
            {
                "schema": "third_party_repository_artifact_audit_v1",
                "every_tracked_file_was_hashed": self.every_tracked_file_was_hashed,
                "rules": list(self.rules),
                "allowed_exceptions": list(self.allowed_exceptions),
                "findings": [
                    {"path": item.path, "rule": item.rule, "detail": item.detail}
                    for item in self.findings
                ],
            },
            length=64,
        )
        if self.audit_fingerprint and self.audit_fingerprint != expected:
            raise RepositoryArtifactError(
                "audit_fingerprint does not cover what the audit found"
            )
        object.__setattr__(self, "audit_fingerprint", expected)

    @property
    def clean(self) -> bool:
        return not self.findings


def tracked_files(repository_root: Path) -> tuple[str, ...]:
    """Every path Git tracks, as forward-slash relative paths.

    Reads Git rather than walking the filesystem, on purpose: the question is
    what the *public repository* holds, and a working tree also holds the
    workspace, the virtualenv and whatever the last run left behind.
    """
    try:
        completed = subprocess.run(
            ("git", "-C", str(repository_root), "ls-files", "-z"),
            check=False,
            capture_output=True,
            timeout=60,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise RepositoryArtifactError(
            f"cannot read the tracked file list with Git: {exc}"
        ) from exc
    if completed.returncode != 0:
        detail = completed.stderr.decode("utf-8", "replace").strip()
        raise RepositoryArtifactError(
            "cannot read the tracked file list with Git"
            + (f": {detail}" if detail else "")
        )
    names = completed.stdout.decode("utf-8", "surrogateescape").split("\0")
    return tuple(sorted(name for name in names if name))


def _suffixes(path: str) -> tuple[str, ...]:
    """Every suffix of a path, lowercased.

    ``checkpoint.pth.tar`` has two, and a rule that looked only at the last one
    would see an archive and miss the checkpoint.
    """
    return tuple(suffix.lower() for suffix in PurePosixPath(path).suffixes)


def audit_repository_artifacts(repository_root: Path) -> RepositoryArtifactAudit:
    """Run every rule over every tracked file and report what fired.

    Returns a report rather than raising, because the caller publishing evidence
    needs to say what was scanned even when nothing was found — an audit that
    only spoke up on failure would be indistinguishable from an audit that never
    ran. :func:`require_no_third_party_bytes_in_git` is the raising wrapper.
    """
    repository_root = Path(repository_root)
    paths = tracked_files(repository_root)
    findings: list[RepositoryFinding] = []
    hashed = 0

    for path in paths:
        name = PurePosixPath(path).name
        lowered_name = name.lower()
        suffixes = _suffixes(path)
        segments = set(PurePosixPath(path).parts[:-1])
        exempt = path in ALLOWED_SYNTHETIC_FIXTURES

        if lowered_name in KNOWN_CHECKPOINT_FILENAMES:
            findings.append(
                RepositoryFinding(
                    path=path,
                    rule="known_checkpoint_filename",
                    detail=f"{name} is a published checkpoint filename",
                )
            )
        for suffix in suffixes:
            if suffix in MODEL_WEIGHT_SUFFIXES:
                findings.append(
                    RepositoryFinding(
                        path=path,
                        rule="model_weight_extension",
                        detail=f"{suffix} holds serialized model parameters",
                    )
                )
            if suffix in RUNTIME_BINARY_SUFFIXES:
                findings.append(
                    RepositoryFinding(
                        path=path,
                        rule="runtime_bundle_or_binary",
                        detail=f"{suffix} is a compiled object or bundle",
                    )
                )
            if suffix in ARCHIVE_SUFFIXES:
                findings.append(
                    RepositoryFinding(
                        path=path,
                        rule="source_or_artifact_archive",
                        detail=f"{suffix} is how an upstream artifact arrives",
                    )
                )
            if suffix in DATASET_IMAGE_SUFFIXES and not exempt:
                findings.append(
                    RepositoryFinding(
                        path=path,
                        rule="dataset_or_biometric_image",
                        detail=(
                            f"{suffix} is an image or template format; "
                            "redistribution-restricted imagery is never tracked "
                            "(docs/adr/0004)"
                        ),
                    )
                )
        overlap = sorted(segment.lower() for segment in segments)
        for segment in overlap:
            repository_owned_policy_module = (
                segment == "third_party"
                and path in _REPOSITORY_OWNED_THIRD_PARTY_MODULES
            )
            if (
                segment in FORBIDDEN_PATH_SEGMENTS
                and not repository_owned_policy_module
            ):
                findings.append(
                    RepositoryFinding(
                        path=path,
                        rule="forbidden_third_party_path",
                        detail=f"{segment!r} is a directory for holding upstream bytes",
                    )
                )
                break

        absolute = repository_root / PurePosixPath(path)
        try:
            size = absolute.stat().st_size
        except OSError:
            # Tracked but absent from this checkout — a sparse checkout, or a
            # path Git knows about that the filesystem does not. Nothing to hash
            # and nothing to weigh; the name-based rules above already ran.
            continue
        if size > MAX_TRACKED_FILE_BYTES:
            findings.append(
                RepositoryFinding(
                    path=path,
                    rule="oversized_tracked_file",
                    detail=(
                        f"{size} bytes; no file this repository legitimately "
                        f"tracks exceeds {MAX_TRACKED_FILE_BYTES}"
                    ),
                )
            )
        digest = hashlib.sha256(absolute.read_bytes()).hexdigest()
        hashed += 1
        if digest in KNOWN_UPSTREAM_ARTIFACT_DIGESTS:
            findings.append(
                RepositoryFinding(
                    path=path,
                    rule="known_upstream_artifact_digest",
                    detail=(
                        "these are the exact bytes of "
                        f"{KNOWN_UPSTREAM_ARTIFACT_DIGESTS[digest]}"
                    ),
                )
            )

    return RepositoryArtifactAudit(
        tracked_file_count=len(paths),
        hashed_file_count=hashed,
        rules=GUARD_RULES,
        allowed_exceptions=tuple(sorted(ALLOWED_SYNTHETIC_FIXTURES)),
        findings=tuple(findings),
    )


def require_no_third_party_bytes_in_git(repository_root: Path) -> RepositoryArtifactAudit:
    """The raising form, for a gate.

    Raises:
        RepositoryArtifactError: at least one tracked file tripped a rule, listed
            by path and rule so the message says what to remove and why.
    """
    audit = audit_repository_artifacts(repository_root)
    if not audit.clean:
        detail = "; ".join(
            f"{finding.path} [{finding.rule}] {finding.detail}"
            for finding in audit.findings
        )
        raise RepositoryArtifactError(
            f"third-party bytes are tracked in this public repository: {detail}"
        )
    return audit
